// complete_rustc_resolution.rs - Complete rustc main resolution with all crates
// Generated by step4_bootstrap - Complete Rustc Resolution

use split_decls_genesis::{resolve_qualified_dependency};
use std::collections::{HashMap, VecDeque};
use serde_json;

fn main() {
    println!("🎯 COMPLETE RUSTC MAIN RESOLUTION (All 77+ Crates)");
    
    // Load complete symbol map with all crates
    let symbol_map_json: HashMap<String, serde_json::Value> = 
        serde_json::from_str(&std::fs::read_to_string("symbol_map.json").unwrap()).unwrap();
    
    let mut symbol_map = HashMap::new();
    for (name, data) in symbol_map_json {
        if let (Some(symbol_type), Some(source_file), Some(crate_name)) = (
            data["symbol_type"].as_str(),
            data["source_file"].as_str(), 
            data["crate_name"].as_str()
        ) {
            let dependencies = data["dependencies"].as_array()
                .map(|arr| arr.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default();
                
            symbol_map.insert(name.clone(), split_decls_genesis::Symbol {
                name: name.clone(),
                symbol_type: symbol_type.to_string(),
                source_file: source_file.to_string(),
                crate_name: crate_name.to_string(),
                dependencies,
            });
        }
    }
    
    println!("✅ Loaded {} symbols from all crates", symbol_map.len());
    
    // Find the real rustc main (from rustc/src/main.rs)
    let rustc_main = symbol_map.iter()
        .find(|(name, symbol)| {
            name.as_str() == "main" && 
            symbol.source_file.contains("rustc/src/main.rs")
        });
    
    match rustc_main {
        Some((name, symbol)) => {
            println!("\n🎯 REAL RUSTC MAIN FOUND:");
            println!("  Function: {}", name);
            println!("  Type: {}", symbol.symbol_type);
            println!("  File: {}", symbol.source_file);
            println!("  Dependencies: {}", symbol.dependencies.len());
            
            // Resolve the key dependency: rustc_driver::main
            println!("\n🔍 KEY DEPENDENCY RESOLUTION:");
            match resolve_qualified_dependency("rustc_driver::main", &symbol_map) {
                Some(location) => {
                    println!("  ✅ rustc_driver::main → {}", location);
                    
                    // Now find the actual rustc_driver_impl main
                    trace_rustc_driver_impl_main(&symbol_map);
                },
                None => {
                    println!("  ❌ rustc_driver::main not resolved");
                    
                    // Try to find it manually
                    find_driver_main_manually(&symbol_map);
                }
            }
            
            // Complete dependency tree
            println!("\n🌳 COMPLETE DEPENDENCY TREE:");
            let tree = build_complete_tree(&symbol_map, name, 5);
            print_dependency_tree(&tree, 0);
            
        },
        None => {
            println!("❌ Real rustc main not found");
            
            // Show all main functions we have
            let all_mains: Vec<_> = symbol_map.iter()
                .filter(|(name, _)| name.as_str() == "main")
                .collect();
            
            println!("📋 All main functions found ({}):", all_mains.len());
            for (name, symbol) in all_mains.iter().take(10) {
                println!("  - {} in {} ({})", name, symbol.crate_name, symbol.source_file);
            }
        }
    }
}

fn find_driver_main_manually(symbol_map: &HashMap<String, split_decls_genesis::Symbol>) {
    println!("  🔍 Searching for rustc_driver_impl main manually...");
    
    // Look for main in rustc_driver_impl
    let driver_impl_main = symbol_map.iter()
        .find(|(name, symbol)| {
            name.as_str() == "main" && symbol.crate_name == "rustc_driver_impl"
        });
    
    match driver_impl_main {
        Some((name, symbol)) => {
            println!("  ✅ Found rustc_driver_impl::main:");
            println!("    Type: {}", symbol.symbol_type);
            println!("    File: {}", symbol.source_file);
            println!("    Dependencies: {}", symbol.dependencies.len());
            
            trace_dependencies(symbol, &symbol_map, 3);
        },
        None => {
            // Show what rustc_driver_impl symbols we have
            let driver_symbols: Vec<_> = symbol_map.iter()
                .filter(|(_, symbol)| symbol.crate_name == "rustc_driver_impl")
                .collect();
            
            println!("  📋 rustc_driver_impl symbols ({}):", driver_symbols.len());
            for (name, _) in driver_symbols.iter().take(10) {
                println!("    - {}", name);
            }
        }
    }
}

fn trace_rustc_driver_impl_main(symbol_map: &HashMap<String, split_decls_genesis::Symbol>) {
    println!("  🔧 Tracing into rustc_driver_impl...");
    
    let driver_impl_main = symbol_map.iter()
        .find(|(name, symbol)| {
            name.as_str() == "main" && symbol.crate_name == "rustc_driver_impl"
        });
    
    if let Some((_, symbol)) = driver_impl_main {
        println!("    ✅ rustc_driver_impl::main found:");
        println!("      Type: {}", symbol.symbol_type);
        println!("      Dependencies: {}", symbol.dependencies.len());
        
        trace_dependencies(symbol, symbol_map, 2);
    }
}

fn trace_dependencies(symbol: &split_decls_genesis::Symbol, symbol_map: &HashMap<String, split_decls_genesis::Symbol>, depth: usize) {
    println!("    🔍 Dependencies (showing first 10):");
    
    let mut resolved = 0;
    let mut unresolved = 0;
    
    for (i, dep) in symbol.dependencies.iter().take(10).enumerate() {
        // Skip jemalloc and macos
        if dep.contains("jemalloc") || dep.contains("macos") || dep.contains("_rjem_") {
            continue;
        }
        
        match resolve_qualified_dependency(dep, symbol_map) {
            Some(location) => {
                resolved += 1;
                println!("      {}. ✅ {} → {}", i+1, dep, location);
            },
            None => {
                unresolved += 1;
                println!("      {}. ❌ {}", i+1, dep);
            }
        }
    }
    
    println!("    📊 Resolution: {}/{} ({:.1}%)", 
        resolved, resolved + unresolved, 
        (resolved as f64 / (resolved + unresolved) as f64) * 100.0);
}

fn build_complete_tree(symbol_map: &HashMap<String, split_decls_genesis::Symbol>, root: &str, max_depth: usize) -> HashMap<String, Vec<String>> {
    let mut tree = HashMap::new();
    let mut queue = VecDeque::new();
    let mut visited = std::collections::HashSet::new();
    
    queue.push_back((root.to_string(), 0));
    
    while let Some((symbol_name, depth)) = queue.pop_front() {
        if depth >= max_depth || visited.contains(&symbol_name) {
            continue;
        }
        
        visited.insert(symbol_name.clone());
        
        if let Some(symbol) = symbol_map.get(&symbol_name) {
            let mut children = Vec::new();
            
            for dep in &symbol.dependencies {
                if !dep.contains("jemalloc") && !dep.contains("macos") && dep.len() > 2 {
                    children.push(dep.clone());
                    if depth < max_depth - 1 {
                        queue.push_back((dep.clone(), depth + 1));
                    }
                }
            }
            
            tree.insert(symbol_name, children);
        }
    }
    
    tree
}

fn print_dependency_tree(tree: &HashMap<String, Vec<String>>, depth: usize) {
    if depth > 3 { return; }
    
    let indent = "  ".repeat(depth);
    
    for (symbol, deps) in tree.iter().take(5) {
        println!("{}├── {} ({} deps)", indent, symbol, deps.len());
        
        for dep in deps.iter().take(3) {
            println!("{}│   └── {}", indent, dep);
        }
        
        if deps.len() > 3 {
            println!("{}│   └── ... and {} more", indent, deps.len() - 3);
        }
    }
}
